// === 08 Подготовка ссылки согласования ===
// Кодируем полный объект заявки (requestId, createdAt, client...) в base64,
// чтобы передать его через URL менеджеру без хранения состояния между вызовами
// (устраняет баг с $('05 Заявка валидна?2') при разрыве executions).
const item = $json;
const payload = {
  requestId: item.requestId,
  createdAt: item.createdAt,
  client: item.client,
};
const encoded = Buffer.from(JSON.stringify(payload), 'utf-8').toString('base64');
const reqParam = encodeURIComponent(encoded);
const baseUrl = 'https://kazinfoteh.app.n8n.cloud';
const approvalUrl = `${baseUrl}/webhook/manager/approval?req=${reqParam}`;

return [{ json: { ...item, approvalUrl } }];

// === 09c Проверка решения и даты ===
// Решение менеджера приходит из HTML-формы (POST), а не из Telegram sendAndWait.
// Исходные данные заявки восстанавливаются из base64 (поле req), т.к. форма и
// отправка решения выполняются в ДРУГОМ execution, чем приём заявки от клиента —
// прямая ссылка на узел $('05 Заявка валидна?2') здесь невозможна и не нужна.
const body = $json.body || {};
const errors = [];

let request = null;
try {
  const decoded = Buffer.from(decodeURIComponent(body.req || ''), 'base64').toString('utf-8');
  request = JSON.parse(decoded);
  if (!request || !request.client || !request.requestId) throw new Error('bad shape');
} catch (e) {
  return [{ json: { success: false, errors: ['Не удалось прочитать данные заявки. Ссылка повреждена или устарела.'] } }];
}

const decision = String(body.decision || '').trim();
const comment = String(body.comment || '').trim();
const action = String(body.action || '').trim();
const trafficType = String(body.trafficType || '').trim();
const connectionDate = body.connectionDate ? String(body.connectionDate).trim() : '';
let operators = [];
if (Array.isArray(body.operators)) operators = body.operators;
else if (typeof body.operators === 'string' && body.operators) operators = body.operators.split(',').map(s => s.trim()).filter(Boolean);

if (!decision || !['Согласовать', 'Отклонить'].includes(decision)) {
  errors.push('Укажите решение по заявке (Согласовать/Отклонить).');
}

if (decision === 'Отклонить' && !comment) {
  errors.push('При отклонении заявки укажите комментарий.');
}

if (decision === 'Согласовать') {
  if (!action || !['Подключение', 'Отключение'].includes(action)) {
    errors.push('Укажите действие: Подключение или Отключение.');
  }
  if (!trafficType || !['Локал', 'Межнар'].includes(trafficType)) {
    errors.push('Укажите тип трафика: Локал или Межнар.');
  }
  if (operators.length === 0) {
    errors.push('Выберите хотя бы одного оператора.');
  }
  if (action === 'Подключение') {
    if (!connectionDate) {
      errors.push('Укажите дату подключения.');
    } else {
      const selectedDate = new Date(connectionDate + 'T00:00:00');
      if (isNaN(selectedDate.getTime())) {
        errors.push('Некорректная дата подключения.');
      } else {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        if (selectedDate < today) {
          errors.push('Дата подключения не может быть в прошлом.');
        }
        const dayOfWeek = selectedDate.getDay();
        if (dayOfWeek === 0 || dayOfWeek === 6) {
          errors.push('Дата подключения не может быть выходным днем (суббота или воскресенье).');
        }
      }
    }
  }
}

if (errors.length > 0) {
  return [{ json: { success: false, errors } }];
}

if (decision === 'Отклонить') {
  return [{
    json: {
      ...request,
      status: 'REJECTED',
      updatedAt: new Date().toISOString(),
      approved: false,
      decision,
      comment,
      success: true,
    }
  }];
}

const clientAction = request.client.action;
const actionOverridden = clientAction && clientAction !== action;

return [{
  json: {
    ...request,
    status: 'PROCESSING',
    updatedAt: new Date().toISOString(),
    approved: true,
    decision,
    comment,
    actionOverridden,
    routing: {
      trafficType,
      action,
      operators,
      connectionDate: connectionDate || null,
    },
    success: true,
  }
}];

// === 02 Generate Request ID ===
const now = new Date();
function pad(n, len = 2) { return String(n).padStart(len, '0'); }
const datePart = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}`;
const timePart = `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const randomPart = Math.random().toString(36).slice(2, 6).toUpperCase();
const requestId = `ALPHA-${datePart}-${timePart}-${randomPart}`;

// Данные приходят из POST webhook в $json.body
const body = $json.body || {};

return [{
  json: {
    ...body,
    requestId,
    createdAt: now.toISOString(),
    updatedAt: now.toISOString(),
    status: 'RECEIVED',
  }
}];

// === 03 Normalize Input ===
function stripInvisible(v) {
  if (v === undefined || v === null) return '';
  return String(v).replace(/^[\n\r\t]+|[\n\r\t]+$/g, '');
}
function safeTrim(v) {
  if (v === undefined || v === null) return '';
  return String(v).trim();
}

const f = $json;

const normalized = {
  action: safeTrim(f.action),
  senderName: stripInvisible(f.senderName),
  companyName: safeTrim(f.companyName),
  bin: safeTrim(f.bin),
  activity: safeTrim(f.activity),
  website: safeTrim(f.website),
  trafficProof: safeTrim(f.trafficProof),
  countriesCount: safeTrim(f.countriesCount),
  headquarters: safeTrim(f.headquarters),
  legalAddress: safeTrim(f.legalAddress),
  foundationDate: safeTrim(f.foundationDate),
  foundationCountry: safeTrim(f.foundationCountry),
  kzMarketSince: safeTrim(f.kzMarketSince),
  founders: safeTrim(f.founders),
  sampleSms: safeTrim(f.sampleSms),
  serverIp: safeTrim(f.serverIp),
  dateToday: new Date().toISOString().split('T')[0],
};

return [{
  json: {
    requestId: f.requestId,
    createdAt: f.createdAt,
    updatedAt: new Date().toISOString(),
    status: 'RECEIVED',
    client: normalized,
  }
}];

// === 04 Validate Request ===
const c = $json.client;
const errors = [];

if (!c.action || !['Подключение', 'Отключение'].includes(c.action)) {
  errors.push('Ошибка в поле «Действие»: выберите «Подключение» или «Отключение».');
}
const isDisconnect = c.action === 'Отключение';

const senderNamePattern = /^[A-Za-z ]{1,11}$/;
if (!c.senderName) {
  errors.push('Ошибка в поле «Имя отправителя/Заголовки»: поле обязательно для заполнения.');
} else if (!senderNamePattern.test(c.senderName)) {
  errors.push('Ошибка в поле «Имя отправителя/Заголовки»: значение должно содержать не более 11 символов и состоять только из латинских букв и пробелов.');
}

const binPattern = /^[0-9]{12}$/;
if (!c.bin) {
  errors.push('Ошибка в поле «БИН компании»: поле обязательно для заполнения.');
} else if (!binPattern.test(c.bin)) {
  errors.push('Ошибка в поле «БИН компании»: БИН должен содержать ровно 12 цифр.');
}

if (!c.companyName || c.companyName.trim().length === 0) {
  errors.push('Ошибка в поле «Название компании/бренда Клиента»: поле обязательно для заполнения.');
} else if (c.companyName.length > 300) {
  errors.push('Ошибка в поле «Название компании/бренда Клиента»: превышена максимальная длина (300 символов).');
}

if (!isDisconnect) {
  if (!c.legalAddress || c.legalAddress.trim().length === 0) {
    errors.push('Ошибка в поле «Юр. адрес компании»: поле обязательно для заполнения.');
  } else if (c.legalAddress.length > 500) {
    errors.push('Ошибка в поле «Юр. адрес компании»: превышена максимальная длина (500 символов).');
  }
  if (!c.activity) errors.push('Ошибка в поле «Описание деятельности»: поле обязательно для заполнения.');
  if (!c.website) errors.push('Ошибка в поле «Сайт Компании / ссылка на приложение»: поле обязательно для заполнения.');
  if (!c.headquarters) errors.push('Ошибка в поле «Географическое нахождение штаб-квартиры Бренда»: поле обязательно для заполнения.');
  if (!c.foundationDate) errors.push('Ошибка в поле «Дата основания Бренда либо компании Клиента»: поле обязательно для заполнения.');
  if (!c.sampleSms) errors.push('Ошибка в поле «Образец текста смс»: поле обязательно для заполнения.');
}

return [{
  json: {
    ...$json,
    status: errors.length ? 'INVALID' : 'VALIDATED',
    updatedAt: new Date().toISOString(),
    validationErrors: errors,
  }
}];

// === 12 Построение объекта заявки (объединение в один item) ===
const src = $json;

// Преобразуем массив операторов в одну строку через запятую (например: "Kcell, Beeline, MTS")
// Если массив пуст или не определен, ставим прочерк
const operatorsString = Array.isArray(src.routing.operators) 
  ? src.routing.operators.join(', ') 
  : (src.routing.operators || '—');

return [{
  json: {
    requestId: src.requestId,
    createdAt: src.createdAt,
    updatedAt: new Date().toISOString(),
    status: 'PROCESSING',
    action: src.routing.action,
    trafficType: src.routing.trafficType,
    operator: operatorsString, // Теперь все операторы в одной строке для одной ячейки
    connectionDate: src.routing.connectionDate,
    docKey: `${src.requestId}_ALL`, // Обновляем ключ, так как заявка теперь единая
    senderName: src.client.senderName,
    companyName: src.client.companyName,
    bin: src.client.bin,
    legalAddress: src.client.legalAddress,
    activity: src.client.activity,
    website: src.client.website,
    trafficProof: src.client.trafficProof,
    countriesCount: src.client.countriesCount,
    headquarters: src.client.headquarters,
    foundationDate: src.client.foundationDate,
    foundationCountry: src.client.foundationCountry,
    kzMarketSince: src.client.kzMarketSince,
    founders: src.client.founders,
    sampleSms: src.client.sampleSms,
    serverIp: src.client.serverIp,
  }
}];

