<script>
(function(){
  var SUBMIT_URL = window.location.origin + '/webhook/manager/approval/submit';
  var form = document.getElementById('approvalForm');
  var result = document.getElementById('result');
  var submitBtn = document.getElementById('submitBtn');
  var loadError = document.getElementById('loadError');
  var approveSection = document.getElementById('approveSection');
  var commentReq = document.getElementById('commentReq');
  var connectionDateField = document.getElementById('field-connectionDate');

  function b64ToUtf8(str){
    return decodeURIComponent(Array.prototype.map.call(atob(str), function(c){
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
  }

  var params = new URLSearchParams(window.location.search);
  var rawReq = params.get('req') || '';
  var request = null;

  try {
    if (!rawReq) throw new Error('missing');
    request = JSON.parse(b64ToUtf8(decodeURIComponent(rawReq)));
    if (!request || !request.client || !request.requestId) throw new Error('shape');
  } catch (e) {
    loadError.classList.remove('hidden');
    form.classList.add('hidden');
    request = null;
  }

  if (request) {
    document.getElementById('viewRequestId').textContent = request.requestId || '—';
    document.getElementById('viewSenderName').textContent = request.client.senderName || '—';
    document.getElementById('viewCompanyName').textContent = request.client.companyName || '—';
    document.getElementById('viewBin').textContent = request.client.bin || '—';
    document.getElementById('viewClientAction').textContent = request.client.action || '—';
    var created = request.createdAt ? new Date(request.createdAt) : null;
    document.getElementById('viewCreatedAt').textContent = created ? created.toLocaleString('ru-RU') : '—';
    document.getElementById('viewActivity').textContent = request.client.activity || '—';
    document.getElementById('viewWebsite').textContent = request.client.website || '—';
    document.getElementById('viewTrafficProof').textContent = request.client.trafficProof || '—';
    document.getElementById('viewCountriesCount').textContent = request.client.countriesCount || '—';
    document.getElementById('viewHeadquarters').textContent = request.client.headquarters || '—';
    document.getElementById('viewLegalAddress').textContent = request.client.legalAddress || '—';
    var foundationDate = request.client.foundationDate ? new Date(request.client.foundationDate) : null;
    document.getElementById('viewFoundationDate').textContent = foundationDate ? foundationDate.toLocaleDateString('ru-RU') : '—';
    document.getElementById('viewFoundationCountry').textContent = request.client.foundationCountry || '—';
    document.getElementById('viewKzMarketSince').textContent = request.client.kzMarketSince || '—';
    document.getElementById('viewFounders').textContent = request.client.founders || '—';
    document.getElementById('viewSampleSms').textContent = request.client.sampleSms || '—';
    document.getElementById('viewServerIp').textContent = request.client.serverIp || '—';

    var defaultAction = request.client.action === 'Отключение' ? 'mgrAction-disconnect' : 'mgrAction-connect';
    var defaultRadio = document.getElementById(defaultAction);
    if (defaultRadio) defaultRadio.checked = true;
    toggleConnectionDate();

    var today = new Date();
    var todayStr = today.getFullYear() + '-' + String(today.getMonth()+1).padStart(2,'0') + '-' + String(today.getDate()).padStart(2,'0');
    document.getElementById('connectionDate').setAttribute('min', todayStr);
  }

  document.getElementById('decision').addEventListener('change', function(e){
    var v = e.target.value;
    approveSection.classList.toggle('hidden', v !== 'Согласовать');
    commentReq.classList.toggle('hidden', v !== 'Отклонить');
  });

  document.querySelectorAll('input[name="mgrAction"]').forEach(function(r){
    r.addEventListener('change', toggleConnectionDate);
  });
  function toggleConnectionDate(){
    var checked = document.querySelector('input[name="mgrAction"]:checked');
    var isConnect = checked && checked.value === 'Подключение';
    connectionDateField.classList.toggle('hidden', !isConnect);
  }

  function isWeekend(dateStr){
    var d = new Date(dateStr + 'T00:00:00');
    var dow = d.getDay();
    return dow === 0 || dow === 6;
  }

  function validate(){
    var errors = [];
    var decision = document.getElementById('decision').value;
    var comment = document.getElementById('comment').value.trim();

    if (!decision) {
      errors.push('Укажите решение по заявке (Согласовать/Отклонить)');
      return { errors: errors };
    }

    if (decision === 'Отклонить') {
      if (!comment) errors.push('При отклонении заявки укажите комментарий');
      return { errors: errors, data: { decision: decision, comment: comment } };
    }

    var mgrActionEl = document.querySelector('input[name="mgrAction"]:checked');
    var trafficTypeEl = document.querySelector('input[name="trafficType"]:checked');
    var operatorEls = document.querySelectorAll('input[name="operators"]:checked');
    var connectionDate = document.getElementById('connectionDate').value;

    if (!mgrActionEl) errors.push('Укажите действие: Подключение или Отключение');
    if (!trafficTypeEl) errors.push('Укажите тип трафика: Локал или Межнар');
    if (operatorEls.length === 0) errors.push('Выберите хотя бы одного оператора');

    var action = mgrActionEl ? mgrActionEl.value : null;
    if (action === 'Подключение') {
      if (!connectionDate) {
        errors.push('Укажите дату подключения');
      } else {
        var selected = new Date(connectionDate + 'T00:00:00');
        var today0 = new Date();
        today0.setHours(0,0,0,0);
        if (selected < today0) errors.push('Дата подключения не может быть в прошлом');
        else if (isWeekend(connectionDate)) errors.push('Дата подключения не может выпадать на выходной день (сб/вс)');
      }
    }

    return {
      errors: errors,
      data: {
        decision: decision,
        comment: comment,
        action: action,
        trafficType: trafficTypeEl ? trafficTypeEl.value : null,
        operators: Array.prototype.map.call(operatorEls, function(el){ return el.value; }),
        connectionDate: action === 'Подключение' ? connectionDate : null
      }
    };
  }

  form.addEventListener('submit', async function(e){
    e.preventDefault();
    if (!request) return;
    result.className = 'result';
    result.style.display = 'none';
    var v = validate();
    if (v.errors.length) {
      result.className = 'result error';
      result.innerHTML = '<h3>⚠️ Проверьте форму</h3><ul>' + v.errors.map(function(x){ return '<li>'+x+'</li>'; }).join('') + '</ul>';
