      window.scrollTo({ top: result.offsetTop - 20, behavior: 'smooth' });
      return;
    }
    submitBtn.disabled = true;
    submitBtn.textContent = 'Отправка...';
    var payload = Object.assign({ req: rawReq }, v.data);
    try {
      var res = await fetch(SUBMIT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      var json = await res.json();
      if (json.success) {
        result.className = 'result success';
        result.innerHTML = '<h3>✅ Решение сохранено</h3><p>Заявка ' + (request ? request.requestId : '') + ' обработана.</p>';
        form.style.display = 'none';
      } else {
        result.className = 'result error';
        result.innerHTML = '<h3>⚠️ Ошибка</h3><ul>' + (json.errors || ['Не удалось сохранить решение']).map(function(x){ return '<li>'+x+'</li>'; }).join('') + '</ul>';
        submitBtn.disabled = false;
        submitBtn.textContent = 'Отправить решение';
      }
      result.style.display = 'block';
      window.scrollTo({ top: result.offsetTop - 20, behavior: 'smooth' });
    } catch (err) {
      result.className = 'result error';
      result.innerHTML = '<h3>❌ Ошибка сети</h3><p>Не удалось отправить решение. Проверьте соединение и попробуйте позже.</p>';
      result.style.display = 'block';
      submitBtn.disabled = false;
      submitBtn.textContent = 'Отправить решение';
    }
  });
})();
</script>
</body>
</html>

