  const dateFmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Almaty', year: 'numeric', month: '2-digit', day: '2-digit' });
  const dayFmt = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Almaty', weekday: 'long' });
  const hourFmt = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Almaty', hour: 'numeric', hour12: false });

  return {
    dateStr: dateFmt.format(date), // Формат YYYY-MM-DD
    dayStr: dayFmt.format(date).toLowerCase(), // 'monday', 'tuesday', и т.д.
    hour: parseInt(hourFmt.format(date), 10)
  };
};

const nowParts = getAlmatyParts(now);
const updatedParts = getAlmatyParts(updatedAt);

// 3. Расчет целевой даты (ваша бизнес-логика)
let targetDate = '';

// Условие: сегодня понедельник И дата обновления понедельник И время обновления < 14:00
if (nowParts.dayStr === 'monday' && updatedParts.dayStr === 'monday' && updatedParts.hour < 14) {
  targetDate = nowParts.dateStr; // Текущий понедельник
} else {
  // Во всех остальных случаях - следующий понедельник
  const d = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Almaty' }));
  const day = d.getDay(); // 0 = воскресенье, 1 = понедельник, и т.д.

  // Математика: сколько дней добавить до следующего понедельника
  // Если сегодня понедельник (1), (8 - 1) % 7 = 0. Оператор || 7 превращает 0 в 7 (добавляем неделю)
  const daysToAdd = (8 - day) % 7 || 7;
  d.setDate(d.getDate() + daysToAdd);

  const nextMondayFmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Almaty', year: 'numeric', month: '2-digit', day: '2-digit' });
  targetDate = nextMondayFmt.format(d);
}

