  col7: `${$json.companyName || ''}\nБИН: ${$json.bin || ''}`
};

if (isLastRowEmpty) {
  const requests = [];
  if (cellStartIndices[6]) requests.push({ insertText: { location: { index: cellStartIndices[6], tabId: 't.0' }, text: newData.col7 } });
  if (cellStartIndices[5]) requests.push({ insertText: { location: { index: cellStartIndices[5], tabId: 't.0' }, text: newData.col6 } });
  if (cellStartIndices[4]) requests.push({ insertText: { location: { index: cellStartIndices[4], tabId: 't.0' }, text: newData.col5 } });
  if (cellStartIndices[3]) requests.push({ insertText: { location: { index: cellStartIndices[3], tabId: 't.0' }, text: newData.col4 } });
  if (cellStartIndices[2]) requests.push({ insertText: { location: { index: cellStartIndices[2], tabId: 't.0' }, text: newData.col3 } });
  if (cellStartIndices[1]) requests.push({ insertText: { location: { index: cellStartIndices[1], tabId: 't.0' }, text: newData.col2 } });
  if (cellStartIndices[0]) requests.push({ insertText: { location: { index: cellStartIndices[0], tabId: 't.0' }, text: newData.col1 } });

  return [{ json: { docId: docResponse.documentId || docResponse.docId || $json.documentId, action: 'insert_text', bodyPayload: JSON.stringify({ requests }) } }];
} else {
  return [{ json: { docId: docResponse.documentId || docResponse.docId || $json.documentId, action: 'insert_row', tableStartIndex: parseInt(tableStartIndex), lastRowIndex: rows.length - 1 } }];
}
